DomKey::DomKey() : tag_(Tag::kNamedKey) {
  data_.named_key = NamedDomKey();
}

DomKey::~DomKey() {
  DestroyActive();
}


void DomKey::set_named_key(
    NamedDomKey named_key) {
  if (tag_ != Tag::kNamedKey) {
    DestroyActive();
    tag_ = Tag::kNamedKey;
  }
  data_.named_key = named_key;
}
void DomKey::set_codepoint(
    uint32_t codepoint) {
  if (tag_ != Tag::kCodepoint) {
    DestroyActive();
    tag_ = Tag::kCodepoint;
  }
  data_.codepoint = codepoint;
}

void DomKey::DestroyActive() {
  switch (tag_) {

    case Tag::kNamedKey:

      break;
    case Tag::kCodepoint:

      break;
  }
}
size_t DomKey::Hash(size_t seed) const {
  seed = mojo::internal::HashCombine(seed, static_cast<uint32_t>(tag_));
  switch (tag_) {

    case Tag::kNamedKey:
      return mojo::internal::Hash(seed, data_.named_key);
    case Tag::kCodepoint:
      return mojo::internal::Hash(seed, data_.codepoint);
    default:
      NOTREACHED();
      return seed;
  }
}

bool DomKey::Validate(
    const void* data,
    mojo::internal::ValidationContext* validation_context) {
  return Data_::Validate(data, validation_context, false);
}
