void InputMethodSettings::DestroyActive() {
  switch (tag_) {

    case Tag::kKoreanSettings:

      delete data_.korean_settings;
      break;
    case Tag::kLatinSettings:

      delete data_.latin_settings;
      break;
    case Tag::kPinyinSettings:

      delete data_.pinyin_settings;
      break;
    case Tag::kZhuyinSettings:

      delete data_.zhuyin_settings;
      break;
    case Tag::kNullSettings:

      break;
    case Tag::kJapaneseSettings:

      delete data_.japanese_settings;
      break;
    case Tag::kVietnameseTelexSettings:

      delete data_.vietnamese_telex_settings;
      break;
    case Tag::kVietnameseVniSettings:

      delete data_.vietnamese_vni_settings;
      break;
  }
}

