InputMethodAsyncWaiter::InputMethodAsyncWaiter(
    InputMethod* proxy) : proxy_(proxy) {}

InputMethodAsyncWaiter::~InputMethodAsyncWaiter() = default;

void InputMethodAsyncWaiter::OnFocus(
    InputFieldInfoPtr input_field_info, InputMethodSettingsPtr deprecated_settings, bool* out_success, InputMethodMetadataPtr* out_metadata) {
  base::RunLoop loop;
  proxy_->OnFocus(std::move(input_field_info),std::move(deprecated_settings),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             InputMethodMetadataPtr* out_metadata
,
             bool success,
             InputMethodMetadataPtr metadata) {*out_success = std::move(success);*out_metadata = std::move(metadata);
            loop->Quit();
          },
          &loop,
          out_success,
          out_metadata));
  loop.Run();
}



void InputMethodAsyncWaiter::ProcessKeyEvent(
    PhysicalKeyEventPtr event, KeyEventResult* out_result) {
  base::RunLoop loop;
  proxy_->ProcessKeyEvent(std::move(event),
      base::BindOnce(
          [](base::RunLoop* loop,
             KeyEventResult* out_result
,
             KeyEventResult result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

KeyEventResult InputMethodAsyncWaiter::ProcessKeyEvent(
    PhysicalKeyEventPtr event) {
  KeyEventResult async_wait_result;
  ProcessKeyEvent(std::move(event),&async_wait_result);
  return async_wait_result;
}

void InputMethodAsyncWaiter::IsReadyForTesting(
    bool* out_ready) {
  base::RunLoop loop;
  proxy_->IsReadyForTesting(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_ready
,
             bool ready) {*out_ready = std::move(ready);
            loop->Quit();
          },
          &loop,
          out_ready));
  loop.Run();
}

bool InputMethodAsyncWaiter::IsReadyForTesting(
    ) {
  bool async_wait_result;
  IsReadyForTesting(&async_wait_result);
  return async_wait_result;
}






